#### `Config` Struct:
```cpp
// Structure defining configuration parameters for data directories, database connection details, etc.
struct Config {
    string data_dir;          // Path to raw transaction and chat data files
    string chat_log_dir;      // Path containing chat logs for sentiment analysis
    string transaction_dir;   // Path containing transaction data files
    string output_dir;        // Path for preprocessed results and reports
    string db_host;           // Host name/ IP of PostgreSQL server
    int db_port;             // PostgreSQL port number
    string db_name;          // Name of PostgreSQL database

    Config(string data_dir, 
            string chat_log_dir,
            string transaction_dir,
            string output_dir,
            string db_host,
            int db_port,
            string db_name) :
        data_dir(data_dir),
        chat_log_dir(chat_log_dir),
        transaction_dir(transaction_dir),
        output_dir(output_dir),
        db_host(db_host),
        db_port(db_port),
        db_name(db_name)
    {}
};
